                "value": "90"
              },
              {
                "op": "all",
                "conditions": [
                  {
                    "op": "fact",
                    "path": "/vendor/countryRisk",
                    "operator": "equals",
                    "value": "HIGH"
                  },
                  {
                    "op": "fact",
                    "path": "/vendor/riskScore",
                    "operator": "greater-than-or-equal",
                    "value": "70"
                  }
                ]
              }
            ]
          }
        ]
      },
      "outcome": "reject",
      "onUnknown": "escalate",
      "evidenceRequirementRefs": [
        "financial-evidence"
      ]
    },
